// Auto-generated FieldFactory Component
// Generated by Builder Layer 04

import React, { useState } from 'react';
import {
  TextField, Select, MenuItem, FormControl, InputLabel, Checkbox, FormControlLabel,
  Switch, Radio, RadioGroup, FormLabel, Slider, Autocomplete, Box, IconButton,
  InputAdornment, Typography
} from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';

// ============================================================================
// Field Factory - Renders field by type
// ============================================================================

interface FieldFactoryProps {
  type: string;
  value: any;
  onChange: (value: any) => void;
  label?: string;
  required?: boolean;
  error?: boolean;
  helperText?: string;
  options?: Array<{ value: any; label: string }>;
  disabled?: boolean;
  readOnly?: boolean;
  placeholder?: string;
  [key: string]: any;
}

export const FieldFactory: React.FC<FieldFactoryProps> = ({
  type,
  value,
  onChange,
  label,
  required,
  error,
  helperText,
  options = [],
  disabled = false,
  readOnly = false,
  placeholder,
  ...props
}) => {
  const [showPassword, setShowPassword] = useState(false);
  
  const typeUpper = (type || 'TEXT').toUpperCase();
  
  const commonProps = {
    disabled: disabled || readOnly,
    error: error,
    helperText: error || helperText,
    fullWidth: true,
    size: 'small' as const,
  };

  switch (typeUpper) {
    // Text fields
    case 'TEXT':
      return (
        <TextField
          {...commonProps}
          label={label}
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          required={required}
        />
      );

    case 'EMAIL':
      return (
        <TextField
          {...commonProps}
          type="email"
          label={label}
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          required={required}
        />
      );

    case 'PHONE':
      return (
        <TextField
          {...commonProps}
          type="tel"
          label={label}
          value={value ?? ''}
          onChange={(e) => {
            const formatted = formatPhone(e.target.value);
            onChange(formatted);
          }}
          placeholder="010-0000-0000"
          required={required}
          inputProps={{ maxLength: 13 }}
        />
      );

    case 'NUMBER':
    case 'CALCULATED':
      return (
        <TextField
          {...commonProps}
          type="number"
          label={label}
          value={value ?? ''}
          onChange={(e) => onChange(parseFloat(e.target.value) || null)}
          required={required}
          InputProps={{ readOnly: typeUpper === 'CALCULATED' }}
        />
      );

    case 'PASSWORD':
      return (
        <TextField
          {...commonProps}
          type={showPassword ? 'text' : 'password'}
          label={label}
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          required={required}
          InputProps={{
            endAdornment: (
              <InputAdornment>
                <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                  {showPassword ? <VisibilityOff /> : <Visibility />}
                </IconButton>
              </InputAdornment>
            ),
          }}
        />
      );

    case 'TEXTAREA':
      return (
        <TextField
          {...commonProps}
          multiline
          rows={4}
          label={label}
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          required={required}
          placeholder={placeholder}
        />
      );

    // Date/Time
    case 'DATE':
      return (
        <TextField
          {...commonProps}
          type="date"
          label={label}
          value={value ? value.split('T')[0] : ''}
          onChange={(e) => onChange(e.target.value ? new Date(e.target.value).toISOString() : null)}
          required={required}
          InputLabelProps={{ shrink: true }}
        />
      );

    case 'DATETIME':
      return (
        <TextField
          {...commonProps}
          type="datetime-local"
          label={label}
          value={value ? value.slice(0, 16) : ''}
          onChange={(e) => onChange(e.target.value ? new Date(e.target.value).toISOString() : null)}
          required={required}
          InputLabelProps={{ shrink: true }}
        />
      );

    // Selection
    case 'SELECT':
    case 'CODE':
    case 'ENUM':
      return (
        <FormControl {...commonProps} required={required}>
          <InputLabel>{label}</InputLabel>
          <Select
            value={value ?? ''}
            onChange={(e) => onChange(e.target.value)}
            label={label}
          >
            {options.map((opt) => (
              <MenuItem key={opt.value} value={opt.value}>
                <Box display="flex" justifyContent="space-between" width="100%">
                  <span>{opt.label}</span>
                  <Typography variant="caption" color="text.secondary">
                    {String(opt.value)}
                  </Typography>
                </Box>
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      );

    case 'CHECKBOX':
      return (
        <FormControlLabel
          control={
            <Checkbox
              checked={!!value}
              onChange={(e) => onChange(e.target.checked)}
              disabled={disabled || readOnly}
            />
          }
          label={label}
        />
      );

    case 'SWITCH':
      return (
        <FormControlLabel
          control={
            <Switch
              checked={!!value}
              onChange={(e) => onChange(e.target.checked)}
              disabled={disabled || readOnly}
            />
          }
          label={label}
        />
      );

    case 'RADIO':
      return (
        <FormControl {...commonProps}>
          <FormLabel>{label}</FormLabel>
          <RadioGroup value={value ?? ''} onChange={(e) => onChange(e.target.value)}>
            {options.map((opt) => (
              <FormControlLabel
                key={opt.value}
                value={opt.value}
                control={<Radio />}
                label={opt.label}
              />
            ))}
          </RadioGroup>
        </FormControl>
      );

    case 'AUTOCOMPLETE':
      return (
        <Autocomplete
          value={value ?? null}
          onChange={(_, newValue) => onChange(newValue)}
          options={options}
          getOptionLabel={(opt) => typeof opt === 'string' ? opt : opt.label || String(opt.value)}
          renderInput={(params) => (
            <TextField {...params} label={label} required={required} {...commonProps} />
          )}
          disabled={disabled || readOnly}
        />
      );

    case 'SLIDER':
      return (
        <Box sx={{ width: '100%', px: 1 }}>
          {label && <Typography variant="caption">{label}</Typography>}
          <Slider
            value={value ?? 0}
            onChange={(_, newValue) => onChange(newValue)}
            disabled={disabled || readOnly}
            {...props}
          />
        </Box>
      );

    case 'ADDRESS':
      return (
        <TextField
          {...commonProps}
          label={label}
          value={value?.base || value || ''}
          onChange={(e) => onChange({ ...value, base: e.target.value })}
          placeholder="Address"
          required={required}
        />
      );

    case 'HIDDEN':
      return <input type="hidden" value={value ?? ''} />;

    case 'FILE':
    case 'IMAGE':
      return (
        <Box>
          <Typography variant="body2">
            {value ? (typeof value === 'string' ? value.split('/').pop() : value.name) : 'No file selected'}
          </Typography>
          <input
            type="file"
            accept={typeUpper === 'IMAGE' ? 'image/*' : undefined}
            onChange={(e) => onChange(e.target.files?.[0] || null)}
            disabled={disabled || readOnly}
          />
        </Box>
      );

    default:
      return (
        <TextField
          {...commonProps}
          label={label}
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          required={required}
          placeholder={placeholder}
        />
      );
  }
};

// Helper function to format phone number
const formatPhone = (value: string): string => {
  if (!value) return '';
  const nums = value.replace(/\D/g, '');
  if (nums.length <= 3) return nums;
  if (nums.length <= 7) return `${nums.slice(0, 3)}-${nums.slice(3)}`;
  return `${nums.slice(0, 3)}-${nums.slice(3, 7)}-${nums.slice(7, 11)}`;
};

export default FieldFactory;
